        :0f;
    ];

    n:count[x];
    total:0f;

    i:0;
    while[i<n;
        total:total + x[i];
        i:i+1;
    ];

    mean_val:total % n;

    total_abs_dev:0f;

    i:0;
    while[i<n;
        diff:x[i] - mean_val;
        if[neg[diff];
            diff:neg[diff];
        ];
        total_abs_dev:total_abs_dev + diff;
        i:i+1;
    ];

    :total_abs_dev % n;
    };
```

