find_zero:{[x]
    n: count[x];
    i: n - 1;

    while[(i >= 0) and (x[i] = 0);
        i: i - 1;
    ];

    if[i < 0;
        :0f;
    ];

    degree: i;

    if[degree = 0;
        :0f;
    ];

    if[degree = 1;
        a: x[1];
        b: x[0];
        : neg[b % a];
    ];

    if[degree = 2;
        a: x[2];
        b: x[1];
        c: x[0];
        disc: (b * b) - (4 * a * c);

        if[disc >= 0;
            sqrt_disc: sqrt[disc];
            r1: ((neg[b]) + sqrt_disc) % (2 * a);
            r2: ((neg[b]) - sqrt_disc) % (2 * a);

            if[(abs[r1]) <= (abs[r2]);
                :r1;
            ];
            :r2;
        ];
    ];

    f:{[x0;xv]
        n: count[xv];
        val: 0f;
        i: 0;

        while[i < n;
            val: val + (xv[i] * (x0 xexp i));
            i: i + 1;
        ];

        :val;
    };

    df:{[x0;xv]
        n: count[xv];
        val: 0f;
        i: 1;

        while[i < n;
            coeff: xv[i];
            power: i - 1;

            if[not(power = 0);
                val: val + (coeff * i * (x0 xexp power));
            ];

            if[power = 0;
                val: val + (coeff * i);
            ];

            i: i + 1;
        ];

        :val;
    };

    x0: 0f;
    tol: 1e-8;
    maxiter: 1000;

