median:{[x]
    if[not count[x];
        :0N;
    ];

    sorted_list: asc[x];
    n: count[sorted_list];
    mid: floor (n - 1) % 2;

    if[(n mod 2) = 1;
        :sorted_list[mid];
    ];

    : (sorted_list[mid] + sorted_list[mid + 1]) % 2.0;
    }
```

