```q
is_palindrome:{[x]
    if[not count[x];
        :1b;
    ];

    left:0;
    right:(count[x]) - 1;

    while[left < right;
        if[not (x[left]) ~ x[right];
            :0b;
        ];

        left:left + 1;
        right:right - 1;
    ];

    :1b;
    };
```

