closest_integer:{[x]
    if[not count[x];
        :0n;
    ];

    trimmed:trim x;

    if[not count[trimmed];
        :0n;
    ];

    sign:1;

    firstChar:first trimmed;

    if[firstChar ~ "-";
        sign:-1;
        trimmed:1_trimmed;
    ];

    if[firstChar ~ "+";
        trimmed:1_trimmed;
    ];

    if[not count[trimmed];
        :0n;
    ];

    if[not (trimmed ~ (trimmed where trimmed ~ ".")) or not (trimmed ~ (trimmed where trimmed in "0123456789"));
        :0n;
    ];

    numVal:"F"$trimmed;
    numVal:sign * numVal;

    if[numVal >= 0;
        lowerFloor:floor numVal;
        upperCeil:lowerFloor + 1;
        diffLower:numVal - lowerFloor;
        diffUpper:upperCeil - numVal;

        if[(diffLower < diffUpper);
            :lowerFloor;
        ];

        if[(diffUpper < diffLower);
            :upperCeil;
        ];

        :upperCeil;
    ];

    lowerFloor:floor numVal;
    upperCeil:lowerFloor + 1;
    diffLower:abs[numVal - lowerFloor];
    diffUpper:abs[upperCeil - numVal];

    if[(diffLower < diffUpper);
        :lowerFloor;
    ];

    if[(diffUpper < diffLower);
        :upperCeil;
    ];

    if[abs[lowerFloor] > abs[upperCeil];
        :lowerFloor;
    ];

    :upperCeil;
    };
